"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[84426],{84426:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-games-name-is-kidnapping.png\\"\\n          title=\\"게임의 이름은 유괴\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"랜덤하우스코리아\\"\\n          publishedDate=\\"2010-04-25\\"\\n          isbn=\\"9788925500324\\"\\n          rating=4\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n정교한 서술 트릭과 반전을 극대화한 전통 추리 소설이다.  \\n```인질과 범인이 공모하여 벌이는 유괴극```이라는 파격적인 설정을 하고, 이 모든 과정을 <mark>게임</mark>이라는 프레임으로 재구성한다.  \\n<br>\\n이는 현대 사회의 인간관계와 모든 가치를 승패로 판단하는 차가운 세계관을 나타내는 듯하다.  \\n<br>\\n실제로 작품 속에서 성공은 곧 게임의 승리를 의미하며, 자신의 뛰어난 지적 능력을 바탕으로 지금까지 모든 게임에서 승리해왔다고 자부하는 오만한 엘리트가 등장한다.  \\n하지만 그도 이 커다란 게임 속 <mark>쓸만한 장기말</mark>에 불과하다.  \\n<br>\\n작품 속 곳곳에 이 게임의 본질이 전혀 다른 곳에 있음을 암시하는 복선들이 많이 존재한다.  \\n<br>\\n마지막 순간에 히든카드가 등장하며, 열린 결말로 작품이 마무리된다. 무승부일까?  \\n또 다른 차원의 게임이 시작되었음을 예고한다.  "}')}}]);